// Aktuelle Sprache (Standard: Deutsch)
let currentLanguage = 'de';
const PERMANENT_LOCALE_KEY = 'permanent_user_locale';

function readStoredLanguageForVB() {
  const candidates = [];
  try {
    candidates.push((localStorage.getItem(PERMANENT_LOCALE_KEY) || '').trim());
    candidates.push((sessionStorage.getItem('pwa_language') || '').trim());
    candidates.push((sessionStorage.getItem('selected_language') || '').trim());
    candidates.push((sessionStorage.getItem('user_language') || '').trim());
    candidates.push((sessionStorage.getItem('app_locale') || '').trim());
    candidates.push((sessionStorage.getItem('language') || '').trim());
    candidates.push((localStorage.getItem('pwa_language') || '').trim());
    candidates.push((localStorage.getItem('selected_language') || '').trim());
    candidates.push((localStorage.getItem('user_language') || '').trim());
    candidates.push((localStorage.getItem('app_locale') || '').trim());
    candidates.push((localStorage.getItem('language') || '').trim());
  } catch (e) {}
  return candidates.find(v => !!v) || '';
}

function persistLanguageForVB(lang, manual) {
  if (!lang) return;
  try {
    localStorage.setItem(PERMANENT_LOCALE_KEY, lang);
    sessionStorage.setItem('pwa_language', lang);
    sessionStorage.setItem('selected_language', lang);
    sessionStorage.setItem('language', lang);
    sessionStorage.setItem('user_language', lang);
    sessionStorage.setItem('app_locale', lang);
    localStorage.setItem('pwa_language', lang);
    localStorage.setItem('selected_language', lang);
    localStorage.setItem('language', lang);
    localStorage.setItem('user_language', lang);
    localStorage.setItem('app_locale', lang);
    if (manual) {
      localStorage.setItem('pwa_language_manual', '1');
      sessionStorage.setItem('pwa_language_manual', '1');
    }
  } catch (e) {}
}

// Sprache aus localStorage laden oder Browser-Sprache verwenden
function initLanguage() {
  // ✅ Prüfe zuerst Session/Storage (hat höchste Priorität)
  const savedLanguage = readStoredLanguageForVB();
  if (savedLanguage && translations[savedLanguage]) {
    // ✅ Gespeicherte Sprache hat Priorität
    currentLanguage = savedLanguage;
    persistLanguageForVB(savedLanguage, false); // ✅ Synchron halten
    if (typeof window !== 'undefined' && window.IS_DEBUG) console.log('✅ Sprache aus localStorage geladen:', savedLanguage);
  } else {
    // ✅ Browser-Sprache erkennen beim Seitenstart
    const browserLang = navigator.language || navigator.userLanguage;
    const langCode = browserLang ? browserLang.split('-')[0].toLowerCase() : null;
    if (typeof window !== 'undefined' && window.IS_DEBUG) console.log('🌐 Browser-Sprache erkannt:', browserLang, '→ Code:', langCode);
    
    if (langCode && translations[langCode]) {
      // ✅ Browsersprache ist verfügbar - aktiviere sie sofort
      currentLanguage = langCode;
      persistLanguageForVB(langCode, false); // ✅ Dauerhaft speichern
      if (typeof window !== 'undefined' && window.IS_DEBUG) console.log('✅ Browser-Sprache aktiviert:', langCode);
    } else {
      // ✅ Fallback: Englisch wenn Browsersprache NICHT unterstützt wird
      currentLanguage = 'en';
      persistLanguageForVB('en', false); // ✅ Dauerhaft speichern
      if (typeof window !== 'undefined' && window.IS_DEBUG) console.log('✅ Fallback auf Englisch aktiviert (Browser-Sprache nicht unterstützt)');
    }
  }
  applyTranslations();
  // ✅ Placeholder für Wunschbox-Felder beim initialen Laden setzen
  updateWishboxPlaceholders();
}

// Übersetzung abrufen
function t(key) {
  return translations[currentLanguage]?.[key] || translations['de'][key] || key;
}

// Alle Übersetzungen anwenden
function applyTranslations() {
  // Navigation
  document.querySelectorAll('[data-i18n]').forEach(element => {
    const key = element.getAttribute('data-i18n');
    if (element.tagName === 'INPUT' || element.tagName === 'TEXTAREA') {
      if (element.hasAttribute('placeholder')) {
        element.placeholder = t(key);
      } else {
        element.value = t(key);
      }
    } else {
      element.textContent = t(key);
    }
  });
  document.querySelectorAll('[data-i18n-title]').forEach(element => {
    const key = element.getAttribute('data-i18n-title');
    if (key) element.setAttribute('title', t(key));
  });
  
  // HTML lang Attribut aktualisieren
  document.documentElement.lang = currentLanguage;
  
  // ✅ Placeholder für Wunschbox-Felder aktualisieren
  updateWishboxPlaceholders();
  if (typeof window.updatePageTitle === 'function') window.updatePageTitle();
}

// Sprache ändern
function changeLanguage(lang) {
  if (translations[lang]) {
    currentLanguage = lang;
    persistLanguageForVB(lang, true); // ✅ Dauerhaft speichern + manuelle Wahl markieren
    applyTranslations();
    updateLanguageSelector();
    
    // ✅ Aktualisiere auch die Anzeige im Drawer-Menü
    if (typeof updateDrawerCurrentLanguage === 'function') {
      updateDrawerCurrentLanguage();
    }
    
    // ✅ Aktualisiere Menü-Titel nach Sprachwechsel (aus sessionStorage)
    if (typeof updateDrawerDjName === 'function') {
      updateDrawerDjName(null); // null = liest aus sessionStorage
    }
    
    // ✅ Party-Info-Zeile sofort aktualisieren (Übersetzung reagiert sofort)
    if (typeof updatePartyInfoLine === 'function') {
      if (typeof window !== 'undefined' && window.IS_DEBUG) console.log('✅ Sprache geändert - aktualisiere Party-Info-Zeile sofort');
      updatePartyInfoLine();
    }
    
    // ✅ Header-Branding aktualisieren (für "von" Übersetzung)
    if (typeof updateHeaderBranding === 'function') {
      updateHeaderBranding();
    }
    
    // ✅ Placeholder für Wunschbox-Felder sofort aktualisieren
    updateWishboxPlaceholders();
  }
}

// Sprachauswahl aktualisieren
function updateLanguageSelector() {
  const selector = document.getElementById('languageSelector');
  if (selector) {
    selector.innerHTML = '';
    
    const languages = [
      { code: 'de', flag: '🇩🇪', key: 'lang_german' },
      { code: 'en', flag: '🇬🇧', key: 'lang_english' },
      { code: 'fr', flag: '🇫🇷', key: 'lang_french' },
      { code: 'ru', flag: '🇷🇺', key: 'lang_russian' },
      { code: 'zh', flag: '🇨🇳', key: 'lang_chinese' },
      { code: 'es', flag: '🇪🇸', key: 'lang_spanish' },
      { code: 'tr', flag: '🇹🇷', key: 'lang_turkish' },
      { code: 'pt', flag: '🇵🇹', key: 'lang_portuguese' }
    ];
    
    // Aktuelle Sprache zuerst
    const currentLang = languages.find(l => l.code === currentLanguage);
    const otherLangs = languages.filter(l => l.code !== currentLanguage);
    const sortedLangs = currentLang ? [currentLang, ...otherLangs] : languages;
    
    sortedLangs.forEach(lang => {
      const option = document.createElement('div');
      option.className = 'language-option' + (lang.code === currentLanguage ? ' active' : '');
      // Verwende die Übersetzung der aktuellen Sprache für den Sprachnamen
      const langName = t(lang.key);
      option.innerHTML = `${lang.flag} ${langName}`;
      option.onclick = () => changeLanguage(lang.code);
      selector.appendChild(option);
    });
    
    // Aktualisiere auch den aktuellen Sprachnamen im Button
    const currentLangName = document.getElementById('currentLanguageName');
    if (currentLangName && currentLang) {
      currentLangName.textContent = t(currentLang.key);
    }
  }
}

// ✅ Funktion zum direkten Setzen der Placeholder für Wunschbox-Felder
function updateWishboxPlaceholders() {
  const titleInput = document.getElementById('title');
  const artistInput = document.getElementById('artist');
  const placeholderText = t('tap_for_suggestions');
  
  if (titleInput) {
    titleInput.placeholder = placeholderText;
  }
  if (artistInput) {
    artistInput.placeholder = placeholderText;
  }
}